You'd want a plugin for this, so~
I've moved this thread to Plugin Requests (from MZ Support). Thank you.
For the options window layout, you could try this:
Spoiler:
plugin code
JavaScript:
/*:
 * @target MZ
 * @plugindesc RTL layout for options window.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/180349/
 * @help Free to use and/or modify for any project, no credit required.
 */
// Override - swap positions of status & title on each options item.
Window_Options.prototype.drawItem = function(index) {
    const title = this.commandName(index);
    const status = this.statusText(index);
    const rect = this.itemLineRect(index);
    const statusWidth = this.statusWidth();
    const titleWidth = rect.width - statusWidth;
    this.resetTextColor();
    this.changePaintOpacity(this.isCommandEnabled(index));
    // Changed the following lines.
    this.drawText(status, rect.x,               rect.y, statusWidth, "left");
    this.drawText(title,  rect.x + statusWidth, rect.y, titleWidth, "right");
};
